package com.fooddelivery.delivery.client; import java.util.Map; import org.springframework.cloud.openfeign.FeignClient; import org.springframework.web.bind.annotation.PathVariable; import org.springframework.web.bind.annotation.PutMapping; import org.springframework.web.bind.annotation.RequestBody; import org.springframework.web.bind.annotation.RequestHeader;import org.springframework.web.bind.annotation.GetMapping;import org.springframework.web.bind.annotation.RequestParam;
@FeignClient(name="order-service",url="${order-service.url:http://localhost:8082}") public interface OrderClient { @PutMapping("/internal/orders/{id}/status") void updateStatus(@RequestHeader("X-Internal-Key") String key,@PathVariable("id") long id,@RequestBody Map<String,String> status);@GetMapping("/internal/orders/{id}/owner-access")Map<String,Boolean> ownerAccess(@RequestHeader("X-Internal-Key")String key,@PathVariable("id")long id,@RequestParam("ownerId")long ownerId); }
